import json
import re
from datetime import date

_DAY_FORMAT = re.compile(r'\d{4}-\d{2}-\d{2}')


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(f'malformed JSON: {exc}') from exc
    if not isinstance(parsed, list):
        raise ValueError('top-level JSON value must be an array of rows')
    total_cents = 0
    days = []
    for index, row in enumerate(parsed):
        if not isinstance(row, dict):
            raise ValueError(f'row {index} is not a JSON object')
        tenant = row.get('tenant')
        if not isinstance(tenant, str) or not tenant:
            raise ValueError(f'row {index} has an invalid tenant')
        amount = row.get('amount_cents')
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError(f'row {index} has an invalid amount_cents')
        day = row.get('day')
        if not isinstance(day, str) or not _DAY_FORMAT.fullmatch(day):
            raise ValueError(f'row {index} has an invalid day')
        try:
            date.fromisoformat(day)
        except ValueError as exc:
            raise ValueError(f'row {index} has an invalid day') from exc
        total_cents += amount
        days.append(day)
    return {
        'row_count': len(parsed),
        'total_cents': total_cents,
        'first_day': min(days) if days else None,
        'last_day': max(days) if days else None,
    }
